const dateObj=x=>{let value=String(x||'').replace(/^(\d{4}-\d\d-\d\d) (\d)/,'$1T$2');if(/^\d{4}-\d\d-\d\dT\d\d:\d\d/.test(value)&&!/(Z|[+-]\d\d:\d\d)$/.test(value))value+='-05:00';return new Date(value)};
const day=x=>Number.isNaN(dateObj(x).getTime())?'—':dateObj(x).toLocaleDateString('es-EC',{day:'numeric',month:'short',timeZone:'America/Guayaquil'});
const fullDate=x=>dateObj(x).toLocaleDateString('es-EC',{day:'numeric',month:'long',year:'numeric',timeZone:'America/Guayaquil'});
